/// Pay amount with the fewest coins and return the coins used.
/// coins lists the available denominations; each denomination may be used
/// any number of times. Denominations that are zero or negative are ignored,
/// and a denomination listed more than once counts once. Return the coins of
/// a payment with the fewest coins whose values sum to amount, listed in
/// non-increasing order. When several payments use that fewest number of
/// coins, return the one whose non-increasing list is lexicographically
/// largest (the largest possible first coin, then the largest possible
/// second coin, and so on).
/// Return Some(vec![]) when amount is 0. Return None when amount is negative
/// or when no combination of the denominations sums to amount. amount is at
/// most 10000 and the function must stay fast at that size.
/// >>> make_change(vec![1, 3, 4], 6)
/// Some(vec![3, 3])
/// >>> make_change(vec![2], 3)
/// None
fn make_change(coins: Vec<i64>, amount: i64) -> Option<Vec<i64>> {
    if amount < 0 {
        return None;
    }
    let mut denoms: Vec<i64> = coins.into_iter().filter(|&c| c > 0).collect();
    denoms.sort_unstable_by(|x, y| y.cmp(x));
    denoms.dedup();
    let amount = amount as usize;
    // fewest[x]: fewest coins summing to x, or None if x cannot be made
    let mut fewest: Vec<Option<usize>> = vec![None; amount + 1];
    fewest[0] = Some(0);
    for x in 1..=amount {
        for &c in &denoms {
            let c = c as usize;
            if c <= x {
                if let Some(k) = fewest[x - c] {
                    if fewest[x].map_or(true, |f| k + 1 < f) {
                        fewest[x] = Some(k + 1);
                    }
                }
            }
        }
    }
    fewest[amount]?;
    let mut out = Vec::new();
    let mut rest = amount;
    while rest > 0 {
        // the largest coin that still allows an optimal payment of the rest;
        // every optimal completion then uses only coins no larger than it
        let target = fewest[rest].unwrap() - 1;
        let c = denoms
            .iter()
            .map(|&c| c as usize)
            .find(|&c| c <= rest && fewest[rest - c] == Some(target))
            .unwrap();
        out.push(c as i64);
        rest -= c;
    }
    Some(out)
}
